declarations.type:
∀ {Γ : Type u_1} {spectrum : Set ℝ} {ids : ℝ → ℝ} {labels energy : Γ → ℝ} {spectral : ∀ (γ : Γ), energy γ ∈ spectrum}
  {injective : Function.Injective energy} {labelled : ∀ (γ : Γ), ids (energy γ) = labels γ} {energy_1 : Γ → ℝ}
  {spectral_1 : ∀ (γ : Γ), energy_1 γ ∈ spectrum} {injective_1 : Function.Injective energy_1}
  {labelled_1 : ∀ (γ : Γ), ids (energy_1 γ) = labels γ},
  { energy := energy, spectral := spectral, injective := injective, labelled := labelled } =
      { energy := energy_1, spectral := spectral_1, injective := injective_1, labelled := labelled_1 } →
    energy = energy_1

∀ (N c : ℕ),
  GRWTSK.Spectral.DirichletCut.boundaryFunctional N c =
    { toFun := fun v => ∑ i, if ↑i = c then v.ofLp i else 0, map_add' := ⋯, map_smul' := ⋯ }
